(function(r,f){const x=f();if(typeof module==='object')module.exports=x;else r.BloomState=x})(globalThis,()=>{'use strict';
const STATES=['empty','loading','partial','full','error','offline','permission-denied','first-run'];
function state(value){if(!STATES.includes(value))throw Error('INVALID_STATE');return value}
class RequestState{constructor(){this.epoch=0;this.status='first-run';this.items=[]}begin(){this.status=this.items.length?'partial':'loading';return++this.epoch}accept(epoch,items){if(epoch!==this.epoch)return false;if(!Array.isArray(items)||items.length>500)throw Error('INVALID_ITEMS');this.items=items.slice();this.status=items.length?'full':'empty';return true}reject(epoch,code){if(epoch!==this.epoch)return false;this.status=code==='DENIED'?'permission-denied':code==='OFFLINE'?'offline':'error';return true}cancel(){this.epoch++}}
class ToastQueue{constructor(clock=()=>Date.now()){this.clock=clock;this.waiting=[];this.current=null;this.history=[];this.next=0}push({key,priority=0,id}){if(typeof key!=='string'||!/^[a-z][a-z0-9_.-]{0,79}$/.test(key)||!Number.isInteger(priority)||priority<0||priority>2)throw Error('INVALID_NOTICE');const identity=id||key;if(this.current?.identity===identity||this.waiting.some(x=>x.identity===identity))return null;const n={id:++this.next,identity,key,priority,createdAt:this.clock()};if(this.waiting.length===8){const lowest=this.waiting.reduce((a,x)=>x.priority<a.priority?x:a);if(priority<=lowest.priority)return null;this.waiting.splice(this.waiting.indexOf(lowest),1)}this.waiting.push(n);this.waiting.sort((a,b)=>b.priority-a.priority||a.id-b.id);this.history.unshift({...n});this.history.length=Math.min(this.history.length,50);this.advance();return n.id}advance(){if(!this.current&&this.waiting.length){this.current=this.waiting.shift();this.current.visibleAt=this.clock()}return this.current}dismiss(){this.current=null;return this.advance()}tick(){if(this.current&&this.current.priority<2&&this.clock()-this.current.visibleAt>=6000)this.dismiss();return this.current}}
class UndoSlot{constructor(clock=()=>Date.now()){this.clock=clock;this.ticket=null;this.sequence=0}offer({revision,restore,ttl=10000}){if(typeof restore!=='function'||!Number.isSafeInteger(revision)||ttl<1000||ttl>30000)throw Error('INVALID_UNDO');this.ticket={id:++this.sequence,revision,restore,expires:this.clock()+ttl};return this.ticket.id}async undo(id,currentRevision){const t=this.ticket;if(!t||t.id!==id||this.clock()>t.expires)throw Error('UNDO_EXPIRED');if(currentRevision!==t.revision)throw Error('STALE_STATE');this.ticket=null;return await t.restore()}clear(){this.ticket=null}}
function filterSettings(schema,query,section){if(!Array.isArray(schema)||schema.length>300||typeof query!=='string'||query.length>120)throw Error('INVALID_SETTINGS');const q=query.trim().toLocaleLowerCase();return schema.filter(x=>(!section||x.group===section)&&(!q||(x.label+' '+x.group).toLocaleLowerCase().includes(q)))}function sectionDefaults(schema,section){const result={};for(const x of filterSettings(schema,'',section)){if(x.readOnly||x.danger)continue;result[x.key]=x.value}return result}
return{STATES,state,RequestState,ToastQueue,UndoSlot,filterSettings,sectionDefaults}});
